async def act(page):
    import urllib.parse
    import asyncio

    target_title = "JavaScript SpeechSynthesis API"
    comment_text = "Thanks, this solved my problem."

    # Navigate to the Sample Page using a relative goto (preferred when possible).
    await page.goto("/?page_id=2")
    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        # best-effort pause if networkidle isn't reached
        await asyncio.sleep(1)

    # 1) Try a direct accessible-name lookup for the post link
    found_href = None
    try:
        candidate = page.get_by_role("link", name=target_title)
        if await candidate.count() > 0:
            try:
                found_href = await candidate.nth(0).get_attribute("href")
            except Exception:
                found_href = None
    except Exception:
        found_href = None

    # 2) Fallback: scan all links and match visible text case-insensitively
    if not found_href:
        try:
            all_links = page.get_by_role("link")
            total = await all_links.count()
            for i in range(total):
                try:
                    text = (await all_links.nth(i).inner_text() or "").strip()
                except Exception:
                    text = ""
                if target_title.lower() in text.lower():
                    try:
                        found_href = await all_links.nth(i).get_attribute("href")
                    except Exception:
                        found_href = None
                    if found_href:
                        break
        except Exception:
            found_href = None

    if not found_href:
        print(f"Post link for '{target_title}' not found on the Sample Page.")
        return

    # 3) Resolve relative href and navigate to the post page
    if not found_href.startswith("http"):
        post_url = urllib.parse.urljoin(page.url, found_href)
    else:
        post_url = found_href

    await page.goto(post_url)
    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        await asyncio.sleep(1)

    # 4) Locate a comment textbox (prefer inside <main>), then fill it
    textbox_locator = None
    try:
        main = page.get_by_role("main")
        if await main.count() > 0:
            tb_in_main = main.nth(0).get_by_role("textbox")
            if await tb_in_main.count() > 0:
                textbox_locator = tb_in_main.nth(0)
    except Exception:
        textbox_locator = None

    if textbox_locator is None:
        try:
            all_tb = page.get_by_role("textbox")
            if await all_tb.count() > 0:
                textbox_locator = all_tb.nth(0)
        except Exception:
            textbox_locator = None

    if textbox_locator is None:
        print("No comment textbox found on the post page.")
        return

    try:
        await textbox_locator.fill(comment_text)
    except Exception as e:
        print(f"Failed to fill comment textbox: {e}")
        return

    # 5) Find and click a submit button. Prefer named buttons inside main via full get_by_role path.
    common_button_names = [
        "Post Comment",
        "Submit Comment",
        "Submit",
        "Post",
        "Send Comment",
        "Comment",
        "Leave a comment",
    ]

    clicked = False
    try:
        main_region = page.get_by_role("main").nth(0) if await page.get_by_role("main").count() > 0 else None
    except Exception:
        main_region = None

    # Try named buttons inside main
    if main_region is not None:
        for name in common_button_names:
            try:
                btn = main_region.get_by_role("button", name=name)
                if await btn.count() > 0:
                    await btn.nth(0).click()
                    clicked = True
                    break
            except Exception:
                continue

    # Try any button inside main
    if not clicked and main_region is not None:
        try:
            any_btn_in_main = main_region.get_by_role("button")
            if await any_btn_in_main.count() > 0:
                await any_btn_in_main.nth(0).click()
                clicked = True
        except Exception:
            clicked = False

    # Global fallbacks by name
    if not clicked:
        for name in common_button_names:
            try:
                btn = page.get_by_role("button", name=name)
                if await btn.count() > 0:
                    await btn.nth(0).click()
                    clicked = True
                    break
            except Exception:
                continue

    # Last resort: click any button on the page
    if not clicked:
        try:
            any_btn = page.get_by_role("button")
            if await any_btn.count() > 0:
                await any_btn.nth(0).click()
                clicked = True
        except Exception:
            clicked = False

    if not clicked:
        print("Could not find a submit button to post the comment.")
        return

    # Done — comment filled and submit clicked (click performed as the last interactive action).
    return

